"use client";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid
} from "recharts";
import { useTheme } from "next-themes";

export default function ChartCard({ title, data, dataKey, stroke = "#10B981" }) {
  const hasData = Array.isArray(data) && data.length > 0;
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <div className="rounded-2xl border border-border bg-card p-6 text-foreground shadow-soft">
      <h3 className="text-sm font-semibold">{title}</h3>
      {hasData ? (
        <div className="mt-6 h-48">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={data}>
              <CartesianGrid 
                stroke={isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)"} 
                strokeDasharray="3 3" 
              />
              <XAxis 
                dataKey="label" 
                stroke={isDark ? "#94A3B8" : "#64748b"} 
                fontSize={12} 
              />
              <YAxis 
                stroke={isDark ? "#94A3B8" : "#64748b"} 
                fontSize={12} 
              />
              <Tooltip 
                contentStyle={{ 
                  background: isDark ? "#0F172A" : "#ffffff", 
                  border: isDark ? "1px solid #1e293b" : "1px solid #e2e8f0",
                  color: isDark ? "#e2e8f0" : "#0f172a"
                }} 
              />
              <Line type="monotone" dataKey={dataKey} stroke={stroke} strokeWidth={2} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      ) : (
        <div className="mt-6 flex h-48 items-center justify-center text-sm text-muted">
          No data yet
        </div>
      )}
    </div>
  );
}
